  constructor(passes) {
    this.passes = passes;
  }

  fee(ticket, hours) {
    const cappedHours = Math.min(hours, 8);
    let baseFee = VEHICLES[ticket.type].rate * cappedHours;
    if (ticket.type === 'ev' && ticket.charging) {
      baseFee += 10 * cappedHours;
    }
    if (this.passes.has(ticket.plate)) {
      baseFee = Math.floor(baseFee / 2);
    }
    return baseFee;
  }
}

